using System;using System.IO;using System.Reflection;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;
class Verify{[STAThread]static int Main(){try{File.WriteAllText("verify.log","start\n");var app=new Application();var tv=new TV();File.AppendAllText("verify.log","constructed\n");var method=typeof(TV).GetMethod("Show",BindingFlags.Instance|BindingFlags.NonPublic);foreach(string p in new[]{"应用管理","AI 分析","恢复应用","安装与桌面","文件管理","配置与保护","设备工具"}){method.Invoke(tv,new object[]{p});tv.Measure(new Size(1180,800));tv.Arrange(new Rect(0,0,1180,800));tv.UpdateLayout();var content=(System.Windows.UIElement)tv.Content;content.Measure(new Size(1140,760));content.Arrange(new Rect(0,0,1140,760));content.UpdateLayout();var bmp=new RenderTargetBitmap(1180,800,96,96,PixelFormats.Pbgra32);bmp.Render((Visual)tv.Content);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using(var f=File.Create("verify-"+p+".png"))encoder.Save(f);File.AppendAllText("verify.log",p+" OK\n");}return 0;}catch(Exception ex){File.AppendAllText("verify.log",ex.ToString());return 1;}}}


